// @domain: domains
//! The product's model slice as generated: every class has a route, a graph and a kind,
//! and every one-of field lists its values. Generated by athena-gen — DO NOT EDIT.
#[path = "../src/model.rs"]
#[allow(dead_code)]
mod model;

#[test]
fn every_class_has_a_route_a_graph_and_a_kind() {
    assert!(!model::CLASSES.is_empty(), "a product API with no classes serves nothing");
    for c in model::CLASSES {
        assert!(!c.segment.is_empty() && c.graph.starts_with("urn:") && !c.kind.is_empty(), "{}", c.name);
    }
}

#[test]
fn every_setting_the_runtime_reads_is_declared() {
    for k in ["events.command", "identity.graph_prefix", "identity.issuer", "model.namespace", "model.prefix", "server.bind", "store.endpoint", "store.graph_prefix", "store.kind", "store.password_var", "store.path", "store.user_var"] {
        assert!(model::SETTINGS.iter().any(|(d, _)| *d == k), "{k} is not declared");
    }
}
